int Mark(int value) { Print("mark" + value); return value; }
bool Condition(bool value) { Print("condition"); return value; }
long Add(long first, long second) => first + second;
long Default(long value = true ? 4 : 9L) => value;
void Main() {
    Print(Condition(true) ? Mark(1) : Mark(2));
    Print(Condition(false) ? Mark(3) : Mark(4));
    Print(false ? Mark(5) : true ? Mark(6) : Mark(7));
    Print(true || false ? 10 : 11);
    var v = 0;
    v = false ? 1 : v = 2;
    Print(v);
    Print(true ? v = 3 : v = 4);
    Print(v);
    Print(false ? 1 / 0 : 12L);
    Print(true ? Add(second: Mark(8), first: Mark(9)) : 0);
    Print(false ? "left" : "right");
    Print(Default());
}
